-- =====================================================================
-- Demo: "English Camp 2nd: For Step-Up" (ค่ายภาษาอังกฤษเพื่อพัฒนาทักษะภาษา),
-- taken from its real poster, plus budget figures for the other demo events
-- so the budget table and report have something in every column.
--
-- The camp runs on fixed dates, as the poster says: Mon 23 – Fri 27 Nov 2569
-- (2026), 07.00–18.00 at อาคารเรียนรวมวิทยาศาสตร์ (ร.วท.2). Registration closed
-- on 20 Nov; 26 students registered and checked in on 23 and 24 Nov.
-- Budget, seats and who is responsible follow the department's budget plan
-- (แผนพัฒนานักศึกษา ภาควิชาคอมพิวเตอร์ ปีงบประมาณ 2569, item 2).
--
-- Apply AFTER schema, seed, demo_organizer and seed_blacklist (it fills in the
-- budgets of their events; 1005, 1008 and 1012 get theirs from seed_fy2570_plan). Safe to run again: it removes event 1050
-- (registrations and check-ins cascade) before adding it back.
--   docker exec -i cpsu-etms-mysql mysql --default-character-set=utf8mb4 -uroot cpsu_etms < database/seed_english_camp.sql
-- =====================================================================

USE cpsu_etms;
SET NAMES utf8mb4;

DELETE FROM events WHERE id = 1050;

INSERT INTO events (id, title, description, category, subcategory, program, years, organizer_id, organizer_name, coordinator_id,
  day_mode, date_start, date_end, event_dates, event_times, time_range, reg_start, reg_end,
  attend_mode, place, capacity, budget_planned, budget_other, budget_actual,
  attendee_note, ask_dietary, meals, issue_certificate, refund_method, status, cycle_stage,
  cert_signer_name, cert_signer_title, email_on_register, email_before_event, email_after_event, created_at)
VALUES (1050,
  'English Camp 2nd: For Step-Up ค่ายภาษาอังกฤษเพื่อพัฒนาทักษะภาษา',
  'ค่ายภาษาอังกฤษ 5 วันสำหรับนักศึกษาภาควิชาคอมพิวเตอร์ ฝึกใช้ภาษาอังกฤษผ่านกิจกรรมที่ได้ลงมือทำจริง ทั้งฟัง พูด อ่าน และเขียน ในบรรยากาศสนุกเป็นกันเอง (Learn · Explore · Friends · Grow)

