ติดต่อสอบถาม: ภาควิชาคอมพิวเตอร์ คณะวิทยาศาสตร์ มหาวิทยาลัยศิลปากร โทร 034-272-923 · www.cp.su.ac.th',
  'อบรมเชิงปฏิบัติการ', 'English', 'all', NULL, 2, 'ผศ.โอภาส วงษ์ทวีทรัพย์', 1032,
  'multi', '2026-11-23', '2026-11-27',
  '2026-11-23,2026-11-24,2026-11-25,2026-11-26,2026-11-27',
  '07:00-18:00,07:00-18:00,07:00-18:00,07:00-18:00,07:00-18:00',
  '07.00–18.00 น.', '2026-11-02', '2026-11-20',
  'onsite', 'อาคารเรียนรวมวิทยาศาสตร์ (ร.วท.2) คณะวิทยาศาสตร์', 150, 100000.00, NULL, NULL,
  'เช็คอินทุกวันก่อน 07.30 น. · แต่งกายสุภาพ เตรียมเครื่องเขียน · ต้องเข้าร่วมครบ 5 วันจึงจะได้รับเกียรติบัตร', 1,
  'breakfast,break_am,lunch,break_pm', 1, 'none', 'open', 2,
  'ผศ.ดร. ปิยะ จันทรัศมี', 'หัวหน้าภาควิชาคอมพิวเตอร์', 1, 1, 0, '2026-10-28 10:00:00');

-- ------------------------------------------------------------------ registrants
-- Every student without a suspension (the blacklisted can't register), except
-- a few who didn't sign up; a few declared food needs.
INSERT INTO registrations (id, event_id, user_id, dept, status, attend_via, food_allergy, dietary_pref, registered_at)
SELECT 105000 + ROW_NUMBER() OVER (ORDER BY u.id), 1050, u.id, u.dept, 'registered', 'onsite',
       CASE u.id WHEN 1003 THEN 'กุ้ง' WHEN 1015 THEN 'ถั่วลิสง' END,
       CASE u.id WHEN 1006 THEN 'ฮาลาล' WHEN 1020 THEN 'มังสวิรัติ' WHEN 1009 THEN 'ไม่ทานเนื้อวัว' END,
       TIMESTAMP('2026-11-02' + INTERVAL (u.id % 17) DAY, '19:30:00')
FROM users u
WHERE u.role = 'student'
  AND u.id NOT IN (1010, 1022, 1025)
  AND NOT EXISTS (SELECT 1 FROM blacklist_entries b WHERE b.user_id = u.id AND b.restored_at IS NULL);

-- ------------------------------------------------------------------ check-ins
-- Day 1: all but two. Day 2 (today, morning): most of them so far.
INSERT INTO registration_checkins (registration_id, event_date, checked_in_at)
SELECT r.id, '2026-11-23', TIMESTAMP('2026-11-23', SEC_TO_TIME(6 * 3600 + 40 * 60 + (r.id % 45) * 60))
FROM registrations r WHERE r.event_id = 1050 AND r.user_id NOT IN (1014, 1026);

INSERT INTO registration_checkins (registration_id, event_date, checked_in_at)
SELECT r.id, '2026-11-24', TIMESTAMP('2026-11-24', SEC_TO_TIME(6 * 3600 + 45 * 60 + (r.id % 40) * 60))
FROM registrations r WHERE r.event_id = 1050 AND r.user_id NOT IN (1014, 1026, 1007, 1019, 1023);

-- ------------------------------------------------------------------ budgets of the other demo events
-- budget_planned = งบประมาณเงินรายได้, budget_other = งบประมาณแหล่งอื่น,
-- budget_actual = ใช้จริง (only for events whose last day has passed).
UPDATE events SET budget_planned = 10000, budget_other = NULL, budget_actual = 9200  WHERE id = 1013;  -- within
UPDATE events SET budget_planned = 10000, budget_other = 2000, budget_actual = 12650 WHERE id = 1014;  -- over by 650
UPDATE events SET budget_planned = 10000, budget_other = NULL, budget_actual = 7800  WHERE id = 1015;  -- within
UPDATE events SET budget_planned = 8000,  budget_other = 4000 WHERE id = 1006;

-- ------------------------------------------------------------------ the poster (JPEG, 2048 x 2048, 1:1)
UPDATE events SET poster_url = 'data:image/jpeg;base64,' WHERE id = 1050;
